import{_ as i,C as r,o as h,c as s,a5 as e,E as d}from"./chunks/framework.D_J2JZBr.js";const b=JSON.parse('{"title":"器件、工艺与光电路线","description":"从上科大物理、电磁和半导体基础出发，探索微纳器件、工艺、光子与新型电子学。","frontmatter":{"title":"器件、工艺与光电路线","description":"从上科大物理、电磁和半导体基础出发，探索微纳器件、工艺、光子与新型电子学。"},"headers":[],"relativePath":"learning/devices-and-process/index.md","filePath":"learning/devices-and-process/index.md","lastUpdated":1795531638000}'),o={name:"learning/devices-and-process/index.md"};function n(E,t,c,l,g,p){const a=r("CourseTable");return h(),s("div",null,[t[0]||(t[0]=e('<h1 id="器件、工艺与光电路线" tabindex="-1">器件、工艺与光电路线 <a class="header-anchor" href="#器件、工艺与光电路线" aria-label="Permalink to &quot;器件、工艺与光电路线&quot;">​</a></h1><p>这条路线适合喜欢物理机制、材料结构、实验表征，或想弄明白“晶体管为什么这样工作”的同学。它既能走向传统半导体器件，也能通向光电子、微纳机电、自旋电子与量子相关研究。不同分支的实验方法和理论基础差别很大，课程名称相近不代表可以直接互相替代。</p><h2 id="按学年安排主线" tabindex="-1">按学年安排主线 <a class="header-anchor" href="#按学年安排主线" aria-label="Permalink to &quot;按学年安排主线&quot;">​</a></h2><p>前两年依据 2026 级 EE 培养方案安排基础；后续选修按 2026–2027 年度表给出建议。进阶表格是方向菜单，不要求全部修读。化学、固体物理或量子力学等基础还需结合所选课程另行规划。</p><table tabindex="0"><thead><tr><th>学期</th><th>课程</th><th>为什么放在这里</th></tr></thead><tbody><tr><td>大一秋</td><td>数学分析 I、线性代数；SI100B</td><td>建立数学与计算表达能力</td></tr><tr><td>大一春</td><td>普通物理 I 及实验；EE111/EE111L；数学分析 II</td><td>同时理解物理模型和电路测量</td></tr><tr><td>大二秋</td><td>普通物理 II 及实验；按方案修 EE115A/EE115B 或 EE150</td><td>为能带、场与器件电学打底</td></tr><tr><td>大二春或大三秋</td><td>EE130/EE130P；按目标补化学 I</td><td>电磁学承接数学分析 II；工艺分支还需要化学基础</td></tr><tr><td>大三秋或春</td><td>EE120 半导体器件基础</td><td>2026 级 EE 专业限选之一；官方先修为物理 II 或 EE130</td></tr><tr><td>大三春及以后</td><td>光电分支选 EE131H；满足条件时考虑 EE222</td><td>EE131H 承接 EE130；EE222 官方先修为物理 II</td></tr><tr><td>大四秋或研究生阶段</td><td>器件选 EE220 或 EE2211；工艺选 EE224A</td><td>深入器件机制与微纳加工，分别检查同等基础、电路物理或化学条件</td></tr><tr><td>大四秋或研究生阶段</td><td>光子选 EE2212；MEMS 选 EE224B/EE224J</td><td>EE2212 要求 EE130、EE131H；EE224J 要求 EE224B，是否可同学期修读须确认</td></tr><tr><td>满足基础后的春季</td><td>EE237；或 EE291C</td><td>自旋电子与量子信息的分支入口，各有明确先修，不建议无准备地并行堆课</td></tr></tbody></table>',5)),d(a,{codes:"EE111,EE130,EE120,EE220,EE2211,EE224A,EE131H,EE222,EE2212,EE224B,EE224J,EE237,EE291C"}),t[1]||(t[1]=e('<div class="warning custom-block"><p class="custom-block-title">不是一条自动解锁链</p><p>EE220 的先修是半导体材料与器件、半导体物理原理、固体物理或同等课程，不是官方唯一指定 EE120。EE224A 要求物理 I、化学 I；培养方案中的“化学/生物课程群任选”不能自动当成化学 I。图谱只帮助规划，具体等效认定与本科选研究生课资格必须另行确认。</p></div><h2 id="先选问题-再选分支" tabindex="-1">先选问题，再选分支 <a class="header-anchor" href="#先选问题-再选分支" aria-label="Permalink to &quot;先选问题，再选分支&quot;">​</a></h2><p><strong>电子器件与工艺</strong>：关心电流、阈值、迁移率、界面、缺陷与可靠性。把器件结构与 I–V、C–V 曲线联系起来，学习分离接触效应、几何因素与材料机制。</p><p><strong>光电子与光子学</strong>：关心光的产生、调制、传播和探测。电磁学是共同语言；不同方向还可能需要物理光学、固体物理和量子力学。不要把“硅光”“光计算”“光探测”当成同一类问题。</p><p><strong>MEMS 与柔性电子</strong>：把机械、电学、材料和制造约束一起考虑。微结构的设计、封装与读出电路相互影响，测到信号后还要分析噪声、漂移与重复性。</p><p><strong>自旋与量子相关研究</strong>：除电路与器件外，需要补相应的磁学、量子和统计基础。官方表中 EE237 列出 EE120/EE220、EE111、微积分、线性代数、物理 I；EE291C 列出 EE130、EE131H、EE120、线性代数，应分别核对。</p><h2 id="校外补充资源" tabindex="-1">校外补充资源 <a class="header-anchor" href="#校外补充资源" aria-label="Permalink to &quot;校外补充资源&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/devices-and-process/resources">器件与工艺自学</a>：按半导体基础、PN 结、MOS、电学测量和工艺知识推进。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/fundamentals/">数学、物理与编程基础</a>：补模型推导、数值计算、数据拟合与误差分析。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/analog-ic/resources">模拟电路资源</a>：实验器件最终需要偏置、读出与接口电路，电路知识不能完全放下。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/research/paper-reading">论文阅读方法</a>：先分清实验现象、拟合模型与机制解释，再判断作者结论是否被数据支持。</li></ul><h2 id="可进入的科研方向" tabindex="-1">可进入的科研方向 <a class="header-anchor" href="#可进入的科研方向" aria-label="Permalink to &quot;可进入的科研方向&quot;">​</a></h2><p>从 <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/devices">器件与自旋电子</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/photonics">光子与光电</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/mems-sensors">MEMS 与传感</a> 出发，也可交叉到 <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/power">电源</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/rf-em">射频</a> 和 <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/ai-hardware">AI 硬件</a>。仪器与工艺条件请从 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/research-groups/">上科大平台</a> 了解正式入口，不要推断所有设备都对所有本科生开放。</p><h2 id="实践建议" tabindex="-1">实践建议 <a class="header-anchor" href="#实践建议" aria-label="Permalink to &quot;实践建议&quot;">​</a></h2><ol><li><strong>先能读懂一组数据</strong>：明确器件面积、偏置、温度、扫描方向和单位，做拟合时保留残差与适用范围。单条曲线不能证明重复性或完整物理机制。</li><li><strong>再建立小型模型</strong>：用 Python 复现一个基础器件模型，对比不同参数的影响，区分模型假设与实测事实。</li><li><strong>通过课程或课题组接受实验培训</strong>：洁净室加工、化学品、真空设备、激光和低温系统都有专门安全要求，不能照网上流程自行上手。</li><li><strong>竞赛与实训围绕目标选择</strong>：<a href="/shanghaitech-ic-wiki-dev.github.io/competitions/">竞赛导航</a> 可帮助寻找系统与传感实践；<a href="/shanghaitech-ic-wiki-dev.github.io/competitions/projects/ysyx">一生一芯</a> 和 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/cadence-summer">Cadence 暑期实训</a> 偏数字设计，可作为跨层理解的补充，不是进入器件科研的必要门槛。</li></ol><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/2833/list.htm" target="_blank" rel="noreferrer">学院本科生培养</a>：2026 级 EE 方案，依据官方本地摘录整理。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">2026–2027 学年开课表</a>：课程代码、季节与先修。</li><li><a href="https://sist.shanghaitech.edu.cn/2835/list.htm" target="_blank" rel="noreferrer">学院本硕博课程体系</a>。实际开课及实验准入以正式通知为准。</li></ul>',14))])}const f=i(o,[["render",n]]);export{b as __pageData,f as default};
